src/contexts/FavoritesContext.tsx.fix:
Use functional updaters and persist the computed value:

const addToFavorites = useCallback(async (productId: string) => {
  let next: string[] | undefined;
  setFavorites(prev => { if (prev.includes(productId)) return prev; next = [...prev, productId]; return next; });
  if (next) await saveFavorites(next);
}, [getStorageKey]);

const removeFromFavorites = useCallback(async (productId: string) => {
  let next: string[] = [];
  setFavorites(prev => { next = prev.filter(id => id !== productId); return next; });
  await saveFavorites(next);
}, [getStorageKey]);

toggleFavorite can keep delegating to these. This removes `favorites` from the deps and eliminates the stale-closure overwrite.

Reset synchronously and guard against the async setState with a cancel flag, inlining the load so the captured key is stable:

useEffect(() => {
  setFavorites([]);
  setIsLoading(true);
  let active = true;
  (async () => {
    const key = getStorageKey();
    try {
      const raw = await AsyncStorage.getItem(key);
      const parsed = raw ? JSON.parse(raw) : [];
      if (active && Array.isArray(parsed)) setFavorites(parsed.filter((x: unknown) => typeof x === 'string'));
    } catch (e) { if (active) setFavorites([]); }
    finally { if (active) setIsLoading(false); }
  })();
  return () => { active = false; };
}, [user?.uid]);

